begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
\i helpers/polat_inbound_fixtures.sql
select ok(not has_function_privilege('authenticated','private.polat_prepare_fixture(uuid,uuid,uuid,bigint,text,text,text)','EXECUTE'),'browser cannot prepare replies');
select ok(not has_function_privilege('service_role','private.polat_outcome_fixture(uuid,uuid,text)','EXECUTE'),'service cannot fabricate fake ACK through private fixture writer');
select ok(not has_table_privilege('authenticated','private.polat_inbound_work','SELECT'),'no raw coverage SELECT');
select ok(not has_table_privilege('service_role','private.polat_response_evidence','INSERT'),'no service evidence INSERT');
select ok((select bool_and(relrowsecurity)from pg_class where oid in('private.polat_conversation_controls'::regclass,'private.polat_inbound_work'::regclass,'private.polat_response_evidence'::regclass,'private.polat_work_history'::regclass)),'private RLS defense in depth');
select pg_temp.polat_setup(1);
select is(pg_temp.polat_state(1),'AI_RESPONSE_PENDING','first source has a durable pending owner');
select pg_temp.polat_send(1,'1');
select is((select count(*)from private.polat_inbound_work where tenant_id=pg_temp.polat_id(1,'2000')),1::bigint,'duplicate gateway replay creates one work record');
select is((select count(*)from private.polat_work_history where tenant_id=pg_temp.polat_id(1,'2000')and message_id is not null),1::bigint,'one capture history');
select is(pg_temp.polat_prepare(1)->>'state','PREPARED','fake response prepare permitted');
select is(pg_temp.polat_state(1),'AI_RESPONSE_PENDING','prepared is not delivered');
select is(pg_temp.polat_prepare(1)->>'state','DELIVERY_UNKNOWN','unknown prepare commit never yields replayable payload');
select is(pg_temp.polat_state(1),'DELIVERY_UNKNOWN','unknown preparation is visible durably');
select is(pg_temp.polat_outcome(1,pg_temp.polat_id(1,'9000'),'UNKNOWN'),'DELIVERY_UNKNOWN','lost fake ACK stays unknown');
select throws_ok($$select pg_temp.polat_outcome(1,pg_temp.polat_id(1,'9000'),'FAILED_BEFORE_SEND')$$,'22023',null,'unknown is never converted to blind retry');
select is(pg_temp.polat_outcome(1,pg_temp.polat_id(1,'9000'),'FAKE_ACK'),'AI_RESPONDED','independent fake positive ACK resolves matching operation');
select is(pg_temp.polat_outcome(1,pg_temp.polat_id(1,'9000'),'FAKE_ACK'),'AI_RESPONDED','ACK replay idempotent');
select is((select count(*)from private.polat_response_evidence where tenant_id=pg_temp.polat_id(1,'2000')and stage='FAKE_ACK'),1::bigint,'one immutable fake ACK');
select throws_ok($$update private.polat_response_evidence set stage='UNKNOWN'where tenant_id=pg_temp.polat_id(1,'2000')$$,'42501',null,'fake evidence immutable');
select throws_ok($$delete from private.polat_work_history where tenant_id=pg_temp.polat_id(1,'2000')$$,'42501',null,'history immutable');
select pg_temp.polat_setup(2);
select pg_temp.polat_prepare(2);
select private.polat_claim_human_fixture(pg_temp.polat_id(2,'2000'),pg_temp.polat_conv(2),pg_temp.polat_gen(2));
select is((select runtime_mode::text from public.conversations where id=pg_temp.polat_conv(2)),'HUMAN_TAKEOVER','native takeover used');
select is(pg_temp.polat_outcome(2,pg_temp.polat_id(2,'9000'),'FAKE_ACK'),'DELIVERY_UNKNOWN','late AI ACK cannot override human control');
select is((public.admin_polat_inbound_page_v1(pg_temp.polat_id(2,'2000'))->'items'->0->>'owner_mode'),'HUMAN_ACTIVE','presentation preserves native backend enum');
select pg_temp.polat_setup(3);
select private.polat_claim_human_fixture(pg_temp.polat_id(3,'2000'),pg_temp.polat_conv(3),pg_temp.polat_gen(3));
select is(pg_temp.polat_prepare(3)->>'state','HUMAN_HANDOFF_PENDING','AI blocked after takeover');
select is(pg_temp.polat_prepare(3,'1',pg_temp.polat_id(33,'9000'),'HUMAN')->>'state','PREPARED','assigned authorized human may prepare fake reply');
select is(pg_temp.polat_outcome(3,pg_temp.polat_id(33,'9000'),'FAKE_ACK'),'HUMAN_OWNED','human ACK remains distinct');
select public.set_conversation_runtime_mode(pg_temp.polat_id(3,'2000'),pg_temp.polat_conv(3),'AI_ACTIVE','Synthetic safe return',extensions.gen_random_uuid());
select is(pg_temp.polat_prepare(3,'1',pg_temp.polat_id(34,'9000'))->>'state','HUMAN_HANDOFF_PENDING','return to AI never replays prior source/draft');
select pg_temp.polat_send(3,'2');
select is(pg_temp.polat_prepare(3,'2',pg_temp.polat_id(35,'9000'))->>'state','PREPARED','fresh inbound after return can be handled');
select pg_temp.polat_setup(4);
select is(pg_temp.polat_prepare(4)->>'state','PREPARED','first retry attempt');
select pg_temp.polat_outcome(4,pg_temp.polat_id(4,'9000'),'FAILED_BEFORE_SEND');
select is(pg_temp.polat_prepare(4,'1',pg_temp.polat_id(41,'9000'))->>'state','AI_RESPONSE_PENDING','backoff enforced');
update private.polat_inbound_work set available_at=clock_timestamp()-interval '1 second'where tenant_id=pg_temp.polat_id(4,'2000');
select pg_temp.polat_prepare(4,'1',pg_temp.polat_id(41,'9000'));select pg_temp.polat_outcome(4,pg_temp.polat_id(41,'9000'),'FAILED_BEFORE_SEND');
update private.polat_inbound_work set available_at=clock_timestamp()-interval '1 second'where tenant_id=pg_temp.polat_id(4,'2000');
select pg_temp.polat_prepare(4,'1',pg_temp.polat_id(42,'9000'));select pg_temp.polat_outcome(4,pg_temp.polat_id(42,'9000'),'FAILED_BEFORE_SEND');
select is(pg_temp.polat_state(4),'HUMAN_HANDOFF_PENDING','three explicit failures require human owner');
select is((select attempts from private.polat_inbound_work where tenant_id=pg_temp.polat_id(4,'2000')),3,'persisted lifetime budget');
select is(pg_temp.polat_prepare(4,'1',pg_temp.polat_id(43,'9000'))->>'state','HUMAN_HANDOFF_PENDING','budget cannot be reset by a new command');
select pg_temp.polat_setup(5);
update public.messaging_contacts set contactability='revoked'where tenant_id=pg_temp.polat_id(5,'2000');
select is(pg_temp.polat_prepare(5)->>'state','BLOCKED_WITH_REASON','revoked contact cannot send');
select pg_temp.polat_setup(6);
select public.set_conversation_runtime_mode(pg_temp.polat_id(6,'2000'),pg_temp.polat_conv(6),'PAUSED','Synthetic pause',extensions.gen_random_uuid());
select is(pg_temp.polat_prepare(6)->>'state','BLOCKED_WITH_REASON','pause fails closed');
select throws_ok($$select private.polat_prepare_fixture(pg_temp.polat_id(7,'2000'),pg_temp.polat_message(1),'61b09000-0000-4000-8000-000000000099',1,private.fse_hash('source'),private.fse_hash('x'))$$,'42501',null,'foreign source denied uniformly');
select throws_ok($$select public.admin_polat_inbound_page_v1('61b02000-0000-4000-8000-999999999999')$$,'42501',null,'wrong tenant denied');
select set_config('request.jwt.claim.sub','61b01000-0000-4000-8000-000000000004',true);
select throws_ok($$select public.admin_polat_inbound_page_v1(pg_temp.polat_id(1,'2000'))$$,'42501',null,'readonly denied');
select set_config('request.jwt.claim.sub','61b01000-0000-4000-8000-000000000003',true);
select ok((public.admin_polat_inbound_page_v1(pg_temp.polat_id(1,'2000'))::text)!~'source_hash|body_hash|operation_id|human_owner|provider_user|lease_token|content','analyst sees explicit safe projection');
select throws_ok($$select public.admin_polat_inbound_page_v1(pg_temp.polat_id(1,'2000'),null,null,101)$$,'22023',null,'hard maximum100');
select throws_ok($$select public.admin_polat_inbound_page_v1(pg_temp.polat_id(1,'2000'),null,null,0)$$,'22023',null,'invalid page size');
select throws_ok($$select public.admin_polat_inbound_page_v1(pg_temp.polat_id(1,'2000'),null,'FORCE_SUCCESS')$$,'22023',null,'invalid filter');
select pg_temp.polat_setup(10);
do $$begin for k in 2..31 loop perform pg_temp.polat_send(10,k::text);end loop;end;$$;
create temporary table polat_page as select public.admin_polat_inbound_page_v1(pg_temp.polat_id(10,'2000'))value;
select is(jsonb_array_length((select value->'items'from polat_page)),25,'default page25');
select is((select value->>'has_more'from polat_page),'true','next page exposed');
select is(jsonb_array_length(public.admin_polat_inbound_page_v1(pg_temp.polat_id(10,'2000'),null,null,25,(select value->'next_cursor'from polat_page))->'items'),6,'history available on second page');
select throws_ok($$select public.admin_polat_inbound_page_v1(pg_temp.polat_id(10,'2000'),null,null,26,(select value->'next_cursor'from polat_page))$$,'22023',null,'cursor cannot cross size');
select throws_ok($$select public.admin_polat_inbound_page_v1(pg_temp.polat_id(10,'2000'),null,null,25,(select value->'next_cursor'||'{"tenant":null}'::jsonb from polat_page))$$,'22023',null,'null cursor identity rejected');
select pg_temp.polat_send(10,'32');
select throws_ok($$select public.admin_polat_inbound_page_v1(pg_temp.polat_id(10,'2000'),null,null,25,(select value->'next_cursor'from polat_page))$$,'22023',null,'concurrent insert fences old cursor, refresh required');
select is((select count(*)from public.messages where tenant_id=pg_temp.polat_id(10,'2000')and direction='inbound'),(select count(*)from private.polat_inbound_work where tenant_id=pg_temp.polat_id(10,'2000')),'zero untracked inbound in configured fixture');
select is((select count(*)from public.messages where tenant_id::text like '61b0%'and direction='outbound'),0::bigint,'no actual outbound row or provider action');
select is((select count(*)from private.verified_payment_receipts where tenant_id::text like '61b0%'),0::bigint,'no financial receipt');
select is((select count(*)from public.subscriptions where tenant_id::text like '61b0%'),0::bigint,'no subscription activation');
select pg_temp.polat_setup(20);
select is(private.polat_hold_fixture(pg_temp.polat_id(20,'2000'),pg_temp.polat_message(20),pg_temp.polat_gen(20),'QA_HOLD'),'HUMAN_HANDOFF_PENDING','unsafe AI gets a durable human task');
select is(pg_temp.polat_prepare(20)->>'state','HUMAN_HANDOFF_PENDING','a QA hold cannot be bypassed by another AI attempt');
select pg_temp.polat_setup(21);
select throws_ok($$select private.polat_prepare_fixture(pg_temp.polat_id(21,'2000'),pg_temp.polat_message(21),pg_temp.polat_id(21,'9000'),pg_temp.polat_gen(21),private.fse_hash('wrong source'),private.fse_hash('reply'))$$,'40001',null,'draft must bind exact inbound content');
select pg_temp.polat_prepare(21);
select throws_ok($$select private.polat_outcome_fixture(pg_temp.polat_id(21,'2000'),pg_temp.polat_id(21,'9000'),(pg_temp.polat_receipt(21,pg_temp.polat_id(21,'9000'),'FAKE_ACK')||jsonb_build_object('body_hash',private.fse_hash('wrong')) )::text)$$,'22023',null,'receipt hash mismatch rejected');
select throws_ok($$select private.polat_outcome_fixture(pg_temp.polat_id(21,'2000'),pg_temp.polat_id(21,'9000'),(pg_temp.polat_receipt(21,pg_temp.polat_id(21,'9000'),'FAKE_ACK')||'{"financial_authority":"LIVE"}'::jsonb)::text)$$,'22023',null,'extra financial authority rejected');
select throws_ok($$select private.polat_outcome_fixture(pg_temp.polat_id(21,'2000'),pg_temp.polat_id(21,'9000'),'{"version":1,"version":1}')$$,'22023',null,'pre-JSONB duplicate keys rejected');
select ok(private.polat_can_dispatch_fixture(pg_temp.polat_id(21,'2000'),pg_temp.polat_id(21,'9000'),pg_temp.polat_gen(21)),'prepared source can dispatch only through fake gate');
select private.polat_claim_human_fixture(pg_temp.polat_id(21,'2000'),pg_temp.polat_conv(21),pg_temp.polat_gen(21));
select ok(not private.polat_can_dispatch_fixture(pg_temp.polat_id(21,'2000'),pg_temp.polat_id(21,'9000'),pg_temp.polat_gen(21)),'human takeover immediately fences AI effect');
select pg_temp.polat_setup(22);
select throws_ok($$select private.polat_close_fixture(pg_temp.polat_id(22,'2000'),pg_temp.polat_message(22),pg_temp.polat_id(22,'8000'))$$,'42501',null,'no closure without existing resolved source-linked case');
insert into public.escalation_cases(id,tenant_id,conversation_id,category,severity,status,source_message_id,resolved_at,resolved_by,resolution_code)values(pg_temp.polat_id(22,'8000'),pg_temp.polat_id(22,'2000'),pg_temp.polat_conv(22),'general_review','LOW','RESOLVED',pg_temp.polat_message(22),clock_timestamp(),'61b01000-0000-4000-8000-000000000001','SYNTHETIC_REVIEW');
select private.polat_close_fixture(pg_temp.polat_id(22,'2000'),pg_temp.polat_message(22),pg_temp.polat_id(22,'8000'));
select is(pg_temp.polat_state(22),'CLOSED_WITH_EVIDENCE','closed only with resolved case evidence');
select is((select case_id from private.polat_work_history where tenant_id=pg_temp.polat_id(22,'2000')order by sequence desc limit 1),pg_temp.polat_id(22,'8000'),'closure link is immutable journal evidence');
select pg_temp.polat_setup(23);
select pg_temp.polat_prepare(23);
-- Controlled synthetic time aging, not a measured production latency.
update private.polat_response_evidence set created_at=clock_timestamp()-interval '31 seconds'where false;
select throws_ok($$update private.polat_response_evidence set created_at=clock_timestamp()-interval '31 seconds'where tenant_id=pg_temp.polat_id(23,'2000')$$,'42501',null,'even aging cannot rewrite append-only attempt evidence');
select pg_temp.polat_setup(24);
update private.polat_inbound_work set received_at=clock_timestamp()-interval '6 minutes'where tenant_id=pg_temp.polat_id(24,'2000');
select is(private.polat_refresh_fixture(pg_temp.polat_id(24,'2000'),1),1,'bounded sweep owns one expired unanswered source');
select is(pg_temp.polat_state(24),'HUMAN_HANDOFF_PENDING','expired AI task stays visible for human review');
select throws_ok($$select private.polat_refresh_fixture(pg_temp.polat_id(24,'2000'),101)$$,'22023',null,'sweep hard maximum100');
select pg_temp.polat_setup(25);
create temporary table before_config as select generation,activation_at from private.polat_conversation_controls where tenant_id=pg_temp.polat_id(25,'2000');
select private.polat_configure_fixture(pg_temp.polat_id(25,'2000'),pg_temp.polat_conv(25));
select ok((select (generation,activation_at)=(select generation,activation_at from before_config)from private.polat_conversation_controls where tenant_id=pg_temp.polat_id(25,'2000')),'configuration replay cannot move source activation boundary');
select pg_temp.polat_setup(30);
do $$begin for k in 2..1101 loop perform pg_temp.polat_send(30,k::text);end loop;end;$$;
create temporary table sparse_page as select public.admin_polat_inbound_page_v1(pg_temp.polat_id(30,'2000'),null,'AI_RESPONDED')value;
select is((select value->>'scan_incomplete'from sparse_page),'true','sparse filter has explicit500-source scan budget');
select is((select value->>'has_more'from sparse_page),'true','empty filtered page does not hide later history');
select is(jsonb_array_length((select value->'items'from sparse_page)),0,'no fake match on sparse filter');
update sparse_page set value=public.admin_polat_inbound_page_v1(pg_temp.polat_id(30,'2000'),null,'AI_RESPONDED',25,value->'next_cursor');
select is((select value->>'has_more'from sparse_page),'true','second bounded scan can continue');
update sparse_page set value=public.admin_polat_inbound_page_v1(pg_temp.polat_id(30,'2000'),null,'AI_RESPONDED',25,value->'next_cursor');
select is((select value->>'has_more'from sparse_page),'false','final scan discloses true completeness');
select is(private.polat_refresh_fixture(pg_temp.polat_id(30,'2000'),25),25,'large stale workload bounded25 per cycle');
select is(private.polat_refresh_fixture(pg_temp.polat_id(30,'2000'),25),25,'next cycle makes forward progress');
select is((select count(*)from private.polat_inbound_work where tenant_id=pg_temp.polat_id(30,'2000')and review_at>clock_timestamp()),50::bigint,'sweep does not revisit first25 forever');
select *from finish();rollback;
